/**
 * plugin-manifest — IS marketplace-tier authoring contract #2 (the first codegen-generated contract).
 *
 * GENERATED by scripts/codegen-authoring.ts from the three-artifact composition:
 *   schemas/authoring/v1/upstream-base/plugin-manifest.v1.json   (authored by THEM)
 *   schemas/authoring/v1/marketplace-tier.schema.json#/$defs/universalFolds
 *   schemas/authoring/v1/is-overlay/plugin-manifest.v1.json      (authored by US)
 *   ⇒ schemas/authoring/v1/plugin-manifest.schema.json           (pure allOf)
 *
 * DO NOT EDIT BY HAND — re-run `pnpm run codegen:authoring` after a schema edit.
 * Per DR-044 D8 the Zod validator AND the D7 inline `$comment` effective-required
 * manifest are single-sourced from the JSON Schema: the two layers below are
 * derived field-by-field from the base and overlay `required` arrays + the
 * per-field type/constraint surface; the universal folds are reused by reference
 * from marketplace-tier. The monotonic-additive invariant (the overlay only ADDS
 * required fields and NARROWS constraints on the base) is the 2026-04-28-debacle
 * guard, asserted by the property test in
 * src/__tests__/plugin-manifest-schema.test.ts.
 */

import {
  type AuthoringArtifact,
  type FoldIssue,
  attach,
  requiredFieldsIssues,
  universalFoldsIssues,
} from './marketplace-tier.js';

// ─── Required-field sets (the source of the effective-required manifest) ─────

/** standardFloor — the upstream-base always-required fields (code.claude.com plugins-reference). */
export const PLUGIN_MANIFEST_BASE_REQUIRED = ['name'] as const;

/** The IS-overlay required delta (beyond the base floor). */
export const PLUGIN_MANIFEST_OVERLAY_REQUIRED = [
  'version',
  'description',
  'author',
  'homepage',
  'license',
  'keywords',
  'commands',
] as const;

/** Effective required = base ∪ overlay = the IS 8-field marketplace set (NON-NEGOTIABLE). */
export const PLUGIN_MANIFEST_REQUIRED_FIELDS = [
  ...PLUGIN_MANIFEST_BASE_REQUIRED,
  ...PLUGIN_MANIFEST_OVERLAY_REQUIRED,
] as const;

// ─── Constraint constants (mirror the JSON Schemas exactly) ──────────────────

/** code.claude.com plugins-reference kebab-case name surface (upstream-base). */
export const PLUGIN_NAME_PATTERN = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/;
/** code.claude.com plugins-reference name length ceiling (upstream-base). */
export const PLUGIN_NAME_MAX = 64;
/** Strict SemVer 2.0.0 (is-overlay — stricter than the legacy IS prefix match). */
export const SEMVER_PATTERN =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((item) => typeof item === 'string');
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isUri(value: string): boolean {
  try {
    new URL(value);
    return true;
  } catch {
    return false;
  }
}

// ─── Layer 1: upstream base (authored by THEM) ───────────────────────────────

/**
 * The code.claude.com plugins-reference projection. Required presence of the
 * standardFloor ([name] — the only upstream-required field) + type/format on the
 * upstream-owned fields (kebab-case name, URI homepage/repository, object author
 * with a required inner name, array keywords/commands). Length of `description`
 * is intentionally NOT capped here — the universal disclosureMarkers fold (1536)
 * is the operative cap (encoding a tighter cap would violate the
 * monotonic-additive invariant against the IS 1536 tier).
 */
export function upstreamBaseIssues(artifact: AuthoringArtifact): FoldIssue[] {
  const issues: FoldIssue[] = [...requiredFieldsIssues(artifact, PLUGIN_MANIFEST_BASE_REQUIRED)];

  if ('name' in artifact) {
    const name = artifact['name'];
    if (typeof name !== 'string') {
      issues.push({ message: 'name must be a string', path: ['name'] });
    } else {
      if (name.length > PLUGIN_NAME_MAX) {
        issues.push({
          message: `name must be at most ${PLUGIN_NAME_MAX} characters`,
          path: ['name'],
        });
      }
      if (!PLUGIN_NAME_PATTERN.test(name)) {
        issues.push({
          message: 'name must be kebab-case (lowercase letters, digits, hyphens)',
          path: ['name'],
        });
      }
    }
  }

  if ('version' in artifact && typeof artifact['version'] !== 'string') {
    issues.push({ message: 'version must be a string', path: ['version'] });
  }

  if ('description' in artifact && typeof artifact['description'] !== 'string') {
    issues.push({ message: 'description must be a string', path: ['description'] });
  }

  if ('author' in artifact) {
    const author = artifact['author'];
    if (!isPlainObject(author)) {
      issues.push({ message: 'author must be an object', path: ['author'] });
    } else {
      for (const key of ['name'] as const) {
        if (!(key in author)) {
          issues.push({ message: `author.${key} is required`, path: ['author', key] });
        }
      }
    }
  }

  if ('homepage' in artifact) {
    const homepage = artifact['homepage'];
    if (typeof homepage !== 'string') {
      issues.push({ message: 'homepage must be a string', path: ['homepage'] });
    } else if (!isUri(homepage)) {
      issues.push({ message: 'homepage must be a valid URI', path: ['homepage'] });
    }
  }

  if ('repository' in artifact) {
    const repository = artifact['repository'];
    if (typeof repository !== 'string') {
      issues.push({ message: 'repository must be a string', path: ['repository'] });
    } else if (!isUri(repository)) {
      issues.push({ message: 'repository must be a valid URI', path: ['repository'] });
    }
  }

  if ('license' in artifact && typeof artifact['license'] !== 'string') {
    issues.push({ message: 'license must be a string', path: ['license'] });
  }

  if ('keywords' in artifact && !isStringArray(artifact['keywords'])) {
    issues.push({ message: 'keywords must be an array of strings', path: ['keywords'] });
  }

  if ('commands' in artifact && !isStringArray(artifact['commands'])) {
    issues.push({ message: 'commands must be an array of strings', path: ['commands'] });
  }

  if ('metadata' in artifact && !isPlainObject(artifact['metadata'])) {
    issues.push({ message: 'metadata must be an object', path: ['metadata'] });
  }

  return issues;
}

// ─── Layer 3: IS overlay (authored by US) ────────────────────────────────────

/**
 * The IS-only delta: the seven upstream-optional metadata fields promoted to
 * IS-required (version, description, author, homepage, license, keywords,
 * commands) + the SemVer narrowing on version. A field whose type is already
 * enforced by the base (the overlay only adds it to required) is not re-typed
 * here — its presence is the required check — to keep messages single-sourced.
 */
export function isOverlayIssues(artifact: AuthoringArtifact): FoldIssue[] {
  const issues: FoldIssue[] = [...requiredFieldsIssues(artifact, PLUGIN_MANIFEST_OVERLAY_REQUIRED)];

  if ('version' in artifact) {
    const version = artifact['version'];
    if (typeof version !== 'string') {
      issues.push({ message: 'version must be a string', path: ['version'] });
    } else if (!SEMVER_PATTERN.test(version)) {
      issues.push({ message: 'version must be strict SemVer 2.0.0', path: ['version'] });
    }
  }

  return issues;
}

// ─── The composition (allOf of base + universal folds + overlay) ─────────────

/** Every issue from the three composed layers, in layer order. */
export function pluginManifestIssues(artifact: AuthoringArtifact): FoldIssue[] {
  return [
    ...upstreamBaseIssues(artifact),
    ...universalFoldsIssues(artifact),
    ...isOverlayIssues(artifact),
  ];
}

/** The plugin-manifest contract — pure allOf composition (base ∧ universalFolds ∧ overlay). */
export const PluginManifestSchema = attach(pluginManifestIssues);

export type PluginManifest = AuthoringArtifact;
